require('dotenv').config();
const { google } = require('googleapis');
const { PrismaClient } = require('@prisma/client');
const crypto = require('crypto');
const prisma = new PrismaClient({ datasources: { db: { url: 'postgresql://admin:TI5PIJKYH2G4@34.47.5.151:5432/portal_lrgmedia' } } });

const ENCRYPTION_KEY = Buffer.from('8531DD68B6048AB59B4E772101C303E19CAB1FBF27007322A20354C0B184DE0A', 'hex');
function decrypt(t) { const [iv,tag,cipher]=t.split(':'); const d=crypto.createDecipheriv('aes-256-gcm',ENCRYPTION_KEY,Buffer.from(iv,'hex')); d.setAuthTag(Buffer.from(tag,'hex')); return d.update(cipher,'hex','utf8')+d.final('utf8'); }

(async()=>{
  const row = await prisma.options.findFirst({ where: { option_name: 'google_service', user_id: null } });
  const data = JSON.parse(row.option_value);
  const token = decrypt(data.auth.access_token);
  const auth = new google.auth.OAuth2();
  auth.setCredentials({ access_token: token });
  const drive = google.drive({ version: 'v3', auth });

  const SOURCE = '1X_U8jenEQCBgpaeNpDWChtCNOPf9wTHt';
  const TARGET = '1gHw2wzrpnfLje3TBgElVC5iuqgHi3JfW';

  // List contents of source folder
  const res = await drive.files.list({
    q: \"'\" + SOURCE + \"' in parents\",
    fields: 'files(id, name, mimeType)',
    pageSize: 100,
    supportsAllDrives: true,
    includeItemsFromAllDrives: true
  });

  console.log('Contenu du dossier source (' + res.data.files.length + ' fichiers):');
  res.data.files.forEach(f => console.log('  -', f.name, '(' + f.mimeType + ')'));

  // Move each item to target
  for (const file of res.data.files) {
    try {
      await drive.files.update({
        fileId: file.id,
        addParents: TARGET,
        removeParents: SOURCE,
        fields: 'id, name, parents',
        supportsAllDrives: true,
        includeItemsFromAllDrives: true
      });
      console.log('✅ Déplacé:', file.name);
    } catch(e) {
      console.log('❌ Erreur:', file.name, e.message);
    }
  }

  // Delete empty source folder
  try {
    await drive.files.delete({ fileId: SOURCE, supportsAllDrives: true, includeItemsFromAllDrives: true });
    console.log('🗑️ Dossier source vide supprimé');
  } catch(e) {
    console.log('⚠️ Pas pu supprimer le dossier source:', e.message);
  }

  await prisma.\$disconnect();
})();
" 2>&1

