const portalConfig = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'portal-configs', 'lrgmedia.json'), 'utf8'));
const prisma = new PrismaClient({ datasources: { db: { url: portalConfig.security.database_config.development } } });
const ENCRYPTION_KEY = Buffer.from(portalConfig.security.secrets.encryption_key, 'hex');
function decrypt(t){const[iv,tag,cipher]=t.split(':');const d=crypto.createDecipheriv('aes-256-gcm',ENCRYPTION_KEY,Buffer.from(iv,'hex'));d.setAuthTag(Buffer.from(tag,'hex'));return d.update(cipher,'hex','utf8')+d.final('utf8');}

(async()=>{
  const row=await prisma.options.findFirst({where:{option_name:'google_service',user_id:null}});
  const data=JSON.parse(row.option_value);
  const token=decrypt(data.auth.access_token);
  const auth=new google.auth.OAuth2();auth.setCredentials({access_token:token});
  const drive=google.drive({version:'v3',auth});

  const SOURCE='1faFMshz5vEDLO3y3raI_oPuPOsZPq7vL';
  const TARGET='1dwo9GzgrMOtNPs58Z2lyfrFd96LxrAM_';

  let pageToken=null,moved=0,errors=0;
  do{
    const res=await drive.files.list({q:\"'\"+SOURCE+\"' in parents\",fields:'nextPageToken,files(id,name)',pageSize:100,pageToken,supportsAllDrives:true,includeItemsFromAllDrives:true});
    for(const f of res.data.files){
      try{
        await drive.files.update({fileId:f.id,addParents:TARGET,removeParents:SOURCE,fields:'id',supportsAllDrives:true,includeItemsFromAllDrives:true});
        moved++;console.log('  ✅',f.name);
      }catch(e){errors++;console.log('  ❌',f.name,e.message.substring(0,80));}
    }
    pageToken=res.data.nextPageToken;
  }while(pageToken);

  try{await drive.files.delete({fileId:SOURCE,supportsAllDrives:true,includeItemsFromAllDrives:true});console.log('🗑️ Dossier source supprimé');}catch(e){}

  console.log('\\n✨ '+moved+' fichiers déplacés, '+errors+' erreurs');
  await prisma.\$disconnect();
})();
"

