const portalConfig = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'portal-configs', 'lrgmedia.json'), 'utf8'));
const prisma = new PrismaClient({ datasources: { db: { url: portalConfig.security.database_config.development } } });

(async()=>{
  // Check if any test accounts/projects still have integrations (they shouldn't after deleteMany with cascade)
  const remaining = await prisma.integrations.findMany({
    where:{OR:[
      {resource_type:'account',resource_id:{in:[289,290,291,292,294,295,296]}},
      {resource_type:'project',resource_id:{in:[98,101,102,103,104,131]}}
    ]},
    select:{id:true}
  });
  console.log('Intégrations restantes liées aux tests:', remaining.length);

  // Also check the orphan integration
  try{
    const orph = await prisma.integrations.findUnique({where:{id:2982}});
    console.log('Intégration #2982 encore présente:', !!orph);
  }catch(e){console.log('Intégration #2982 supprimée ✓');}

  await prisma.\$disconnect();
})();
"

